add_filter( 'the_excerpt_rss', 'perfectpixel_feed_hide_excerpt', 99 );
add_filter( 'the_content_feed', 'perfectpixel_feed_hide_content', 99 );

function perfectpixel_feed_hide_excerpt() {
	return esc_html( '{{feed_item_message}}' );
}

function perfectpixel_feed_hide_content() {
	$message = '{{feed_item_message}}';
	return '' === trim( $message ) ? '' : '<p><a href="' . esc_url( get_permalink() ) . '">' . esc_html( $message ) . '</a></p>';
}
